import React, { useState } from 'react';
import { UserRole, AuthUser } from '../types';

const BG_IMAGE = "data:image/jpeg;base64,";

interface RoleConfig {
  id: UserRole;
  label: string;
  desc: string;
  icon: React.ReactNode;
}

const roles: RoleConfig[] = [
  {
    id: 'student',
    label: 'Student Login',
    desc: 'View campus sustainability overview & reports',
    icon: (
      <svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
        <path d="M22 10v6M2 10l10-5 10 5-10 5z"/><path d="M6 12v5c3 3 9 3 12 0v-5"/>
      </svg>
    ),
  },
  {
    id: 'faculty',
    label: 'Faculty Login',
    desc: 'Access energy, water & AI predictions data',
    icon: (
      <svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
        <circle cx="12" cy="8" r="4"/><path d="M4 20c0-4 3.6-7 8-7s8 3 8 7"/><path d="M15 8l2-2 2 2"/>
      </svg>
    ),
  },
  {
    id: 'admin',
    label: 'Admin Login',
    desc: 'Full system access, database & admin tools',
    icon: (
      <svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
        <path d="M12 2l3 6.5L22 9.3l-5 4.9 1.2 6.8L12 18l-6.2 3 1.2-6.8L2 9.3l7-.8z"/>
      </svg>
    ),
  },
];

interface CredentialsFormProps {
  role: RoleConfig;
  onBack: () => void;
  onLogin: (user: AuthUser) => void;
}

const CredentialsForm: React.FC<CredentialsFormProps> = ({ role, onBack, onLogin }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [emailFocus, setEmailFocus] = useState(false);
  const [passFocus, setPassFocus] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) { setError('Please fill in all fields.'); return; }
    if (!/\S+@\S+\.\S+/.test(email)) { setError('Please enter a valid email address.'); return; }
    setError('');
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      onLogin({ email, role: role.id });
    }, 1200);
  };

  return (
    <div style={s.credBox}>
      <button style={s.backBtn} onClick={onBack}>
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
          <path d="M19 12H5M12 5l-7 7 7 7"/>
        </svg>
        Back
      </button>

      <div style={s.roleBadge}>
        <div style={s.roleBadgeIcon}>{role.icon}</div>
        <div>
          <div style={s.roleBadgeLabel}>{role.label}</div>
          <div style={s.roleBadgeDesc}>{role.desc}</div>
        </div>
      </div>

      <div style={s.hrLine} />

      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
        <div style={s.fieldGroup}>
          <label style={s.label}>Email Address</label>
          <div style={{ ...s.inputWrap, ...(emailFocus ? s.inputWrapFocus : {}) }}>
            <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke={emailFocus ? '#2e7d32' : '#aaa'} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink: 0 }}>
              <rect x="2" y="4" width="20" height="16" rx="2"/><path d="M2 7l10 7 10-7"/>
            </svg>
            <input type="email" placeholder="Enter your university email" value={email}
              onChange={e => setEmail(e.target.value)}
              onFocus={() => setEmailFocus(true)} onBlur={() => setEmailFocus(false)}
              style={s.input} autoComplete="email" />
          </div>
        </div>

        <div style={s.fieldGroup}>
          <label style={s.label}>Password</label>
          <div style={{ ...s.inputWrap, ...(passFocus ? s.inputWrapFocus : {}) }}>
            <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke={passFocus ? '#2e7d32' : '#aaa'} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink: 0 }}>
              <rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/>
            </svg>
            <input type={showPass ? 'text' : 'password'} placeholder="Enter your password" value={password}
              onChange={e => setPassword(e.target.value)}
              onFocus={() => setPassFocus(true)} onBlur={() => setPassFocus(false)}
              style={s.input} autoComplete="current-password" />
            <button type="button" onClick={() => setShowPass(!showPass)} style={s.eyeBtn}>
              {showPass
                ? <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="#aaa" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94"/><path d="M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19"/><line x1="1" y1="1" x2="23" y2="23"/></svg>
                : <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="#aaa" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
              }
            </button>
          </div>
        </div>

        <div style={{ textAlign: 'right', marginTop: '-4px' }}>
          <button type="button" style={s.forgotBtn}>Forgot password?</button>
        </div>

        {error && (
          <div style={s.errorBox}>
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#c62828" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/>
            </svg>
            {error}
          </div>
        )}

        <button type="submit" style={s.submitBtn} disabled={loading}>
          {loading ? (
            <span style={{ display: 'flex', gap: '5px', alignItems: 'center' }}>
              {[0, 0.15, 0.3].map((d, i) => (
                <span key={i} style={{ width: 7, height: 7, borderRadius: '50%', background: '#fff', display: 'inline-block', animation: `bounce 0.9s ${d}s infinite` }} />
              ))}
            </span>
          ) : (
            <>
              <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4"/><polyline points="10 17 15 12 10 7"/><line x1="15" y1="12" x2="3" y2="12"/>
              </svg>
              Login as {role.label.split(' ')[0]}
            </>
          )}
        </button>
      </form>
      <style>{`@keyframes bounce { 0%,80%,100%{transform:translateY(0)} 40%{transform:translateY(-7px)} }`}</style>
    </div>
  );
};

interface LoginPageProps {
  onLogin: (user: AuthUser) => void;
}

const LoginPage: React.FC<LoginPageProps> = ({ onLogin }) => {
  const [selectedRole, setSelectedRole] = useState<RoleConfig | null>(null);
  const [hovered, setHovered] = useState<UserRole | null>(null);

  return (
    <div style={s.root}>
      <div style={{ ...s.bgImage, backgroundImage: `url(${BG_IMAGE})` }} />
      <div style={s.overlay} />
      <div style={s.container}>
        {selectedRole ? (
          <CredentialsForm role={selectedRole} onBack={() => setSelectedRole(null)} onLogin={onLogin} />
        ) : (
          <>
            <div style={s.header}>
              <div style={s.leafIcon}>
                <svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M2 22c1.25-1.25 2.5-3 4-4.5C9 14 13 12 20 3c0 0-7 1-11 5s-5.5 8.5-7 14z"/>
                  <path d="M7 17c1-2 3-4 5-5"/>
                </svg>
              </div>
              <h1 style={s.title}>Green Audit System</h1>
              <p style={s.subtitle}>K.R. Mangalam University</p>
              <div style={s.divider} />
              <p style={s.tagline}>Select your role to continue</p>
            </div>

            <div style={s.cardsWrapper}>
              {roles.map(role => (
                <button key={role.id}
                  style={{ ...s.card, ...(hovered === role.id ? s.cardHovered : {}) }}
                  onMouseEnter={() => setHovered(role.id)}
                  onMouseLeave={() => setHovered(null)}
                  onClick={() => setSelectedRole(role)}
                >
                  <div style={{ ...s.iconWrap, ...(hovered === role.id ? s.iconWrapHovered : {}) }}>
                    {role.icon}
                  </div>
                  <span style={s.cardLabel}>{role.label}</span>
                  <span style={s.cardDesc}>{role.desc}</span>
                  <span style={{ ...s.arrow, ...(hovered === role.id ? s.arrowVisible : {}) }}>â</span>
                </button>
              ))}
            </div>

            <p style={s.footer}>Â© {new Date().getFullYear()} K.R. Mangalam University Â· Green Audit Portal</p>
          </>
        )}
      </div>
    </div>
  );
};

export default LoginPage;

